#!/usr/bin/env python3
"""Pre-commit hook ``no-media``: keep third-party media out of the repository.

Fails when a staged or tracked file has a media extension and is not under an allowed path.
The same rules are enforced by ``tests/repo/`` (which imports this module), so there is a single
source of truth. Standard library only; works on Windows, macOS and Linux.

Allowed locations:

* ``assets/sfx/``: sound effects generated by this project (CC0).
* ``docs/img/``: screenshots that are our own or synthetic.
* ``templates/graphics/<id>/preview.png``: preview of a graphics template.
"""

from __future__ import annotations

import fnmatch
import sys

FORBIDDEN_EXTENSIONS = frozenset(
    {
        ".mp4", ".mov", ".mkv", ".webm", ".avi", ".m4v",
        ".gif", ".jpg", ".jpeg", ".png", ".webp", ".bmp", ".tif", ".tiff",
        ".wav", ".mp3", ".m4a", ".aac", ".flac", ".ogg",
    }
)  # fmt: skip
ALLOWED_PATTERNS = (
    "assets/sfx/*",
    "docs/img/*",
    "templates/graphics/*/preview.png",
)


def is_forbidden(path: str) -> bool:
    """True when ``path`` is a media file outside the allowed locations."""
    norm = path.replace("\\", "/").removeprefix("./")
    lowered = norm.lower()
    dot = lowered.rfind(".")
    if dot == -1 or lowered[dot:] not in FORBIDDEN_EXTENSIONS:
        return False
    return not any(fnmatch.fnmatchcase(norm, pattern) for pattern in ALLOWED_PATTERNS)


def main(argv: list[str]) -> int:
    bad = [p for p in argv if is_forbidden(p)]
    if not bad:
        return 0
    if hasattr(sys.stderr, "reconfigure"):
        sys.stderr.reconfigure(encoding="utf-8", errors="replace")
    print("Medios no permitidos en el repositorio:", file=sys.stderr)
    for path in bad:
        print(f"  - {path}", file=sys.stderr)
    print(
        "Solo se versionan medios en assets/sfx/, docs/img/ y templates/graphics/*/preview.png. "
        "Los videos, fotogramas y audios de terceros nunca se suben.",
        file=sys.stderr,
    )
    return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
